package outbox

import (
	"context"
	"crypto/rand"
	"database/sql"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"time"

	"github.com/neerajsinghi/go-outbox/dialect"
)

// DefaultTable is the outbox table name used when [WithTable] is not given.
const DefaultTable = "outbox_messages"

// Message status values stored in the status column.
const (
	StatusPending = "pending"
	StatusSent    = "sent"
	StatusDead    = "dead"
)

// Message is a single event to be delivered through the outbox.
type Message struct {
	// ID uniquely identifies the message. It is generated by Enqueue when
	// empty. Consumers should use it to deduplicate deliveries.
	ID string
	// Topic is the destination (Kafka topic, SQS queue, NATS subject, ...).
	Topic string
	// Key is an optional partition/ordering key.
	Key string
	// Payload is the opaque message body.
	Payload []byte
	// Headers are optional metadata (trace context, content type, ...).
	Headers map[string]string

	// Attempts is the number of delivery attempts already made before the
	// current one. It is populated by the relay and ignored by Enqueue.
	Attempts int
	// CreatedAt is when the message was enqueued. Populated by the relay.
	CreatedAt time.Time
}

// ErrInvalidMessage is returned by Enqueue for messages without a topic.
var ErrInvalidMessage = errors.New("outbox: message topic is required")

// Outbox writes messages into the outbox table. It is safe for concurrent use.
type Outbox struct {
	d     dialect.Dialect
	table string
	now   func() time.Time
}

// Option configures an [Outbox].
type Option func(*Outbox)

// WithTable overrides the outbox table name (default [DefaultTable]).
// The name may be schema-qualified, e.g. "events.outbox".
func WithTable(name string) Option { return func(o *Outbox) { o.table = name } }

// WithClock overrides the time source. Intended for tests.
func WithClock(now func() time.Time) Option { return func(o *Outbox) { o.now = now } }

// New returns an Outbox for the given SQL dialect.
func New(d dialect.Dialect, opts ...Option) (*Outbox, error) {
	o := &Outbox{d: d, table: DefaultTable, now: time.Now}
	for _, opt := range opts {
		opt(o)
	}
	if !dialect.ValidIdentifier(o.table) {
		return nil, fmt.Errorf("outbox: invalid table name %q", o.table)
	}
	return o, nil
}

// Dialect returns the SQL dialect the outbox was created with.
func (o *Outbox) Dialect() dialect.Dialect { return o.d }

// Table returns the outbox table name.
func (o *Outbox) Table() string { return o.table }

// Schema returns the DDL statements for the outbox table. Use it with your
// migration tool of choice, or call [Outbox.CreateSchema].
func (o *Outbox) Schema() []string { return o.d.OutboxSchema(o.table) }

// CreateSchema creates the outbox table and index if they do not exist.
func (o *Outbox) CreateSchema(ctx context.Context, db *sql.DB) error {
	for _, stmt := range o.Schema() {
		if _, err := db.ExecContext(ctx, stmt); err != nil {
			return fmt.Errorf("outbox: create schema: %w", err)
		}
	}
	return nil
}

// Enqueue inserts msg into the outbox as part of tx. The message becomes
// visible to relays only when tx commits; if tx is rolled back the message
// is discarded together with the rest of the business change. That is the
// whole point of the transactional outbox.
//
// It returns the message ID (generated when msg.ID is empty).
func (o *Outbox) Enqueue(ctx context.Context, tx *sql.Tx, msg Message) (string, error) {
	if msg.Topic == "" {
		return "", ErrInvalidMessage
	}
	if msg.ID == "" {
		msg.ID = NewID()
	}
	headers := []byte("{}")
	if len(msg.Headers) > 0 {
		var err error
		if headers, err = json.Marshal(msg.Headers); err != nil {
			return "", fmt.Errorf("outbox: encode headers: %w", err)
		}
	}
	payload := msg.Payload
	if payload == nil {
		payload = []byte{}
	}
	now := o.now().UnixMilli()
	q := o.d.Rebind(fmt.Sprintf(`INSERT INTO %s
		(id, topic, msg_key, payload, headers, status, attempts, next_attempt_at, created_at)
		VALUES (?, ?, ?, ?, ?, ?, 0, ?, ?)`, o.table))
	if _, err := tx.ExecContext(ctx, q, msg.ID, msg.Topic, msg.Key, payload, string(headers), StatusPending, now, now); err != nil {
		return "", fmt.Errorf("outbox: enqueue: %w", err)
	}
	return msg.ID, nil
}

// Counts reports how many messages are in each status. It is cheap enough
// for a metrics scrape on a moderately sized table.
func (o *Outbox) Counts(ctx context.Context, db *sql.DB) (map[string]int, error) {
	rows, err := db.QueryContext(ctx, fmt.Sprintf(`SELECT status, COUNT(*) FROM %s GROUP BY status`, o.table))
	if err != nil {
		return nil, fmt.Errorf("outbox: counts: %w", err)
	}
	defer rows.Close()
	out := map[string]int{StatusPending: 0, StatusSent: 0, StatusDead: 0}
	for rows.Next() {
		var s string
		var n int
		if err := rows.Scan(&s, &n); err != nil {
			return nil, fmt.Errorf("outbox: counts: %w", err)
		}
		out[s] = n
	}
	return out, rows.Err()
}

// PurgeSent deletes sent messages older than olderThan and returns how many
// rows were removed. Run it periodically to keep the table small.
func (o *Outbox) PurgeSent(ctx context.Context, db *sql.DB, olderThan time.Duration) (int64, error) {
	cutoff := o.now().Add(-olderThan).UnixMilli()
	q := o.d.Rebind(fmt.Sprintf(`DELETE FROM %s WHERE status = ? AND sent_at < ?`, o.table))
	res, err := db.ExecContext(ctx, q, StatusSent, cutoff)
	if err != nil {
		return 0, fmt.Errorf("outbox: purge: %w", err)
	}
	return res.RowsAffected()
}

// RetryDead moves dead messages back to pending with a fresh attempt
// budget, e.g. after fixing a downstream outage. It returns the number of
// messages requeued.
func (o *Outbox) RetryDead(ctx context.Context, db *sql.DB) (int64, error) {
	q := o.d.Rebind(fmt.Sprintf(`UPDATE %s SET status = ?, attempts = 0, next_attempt_at = ?,
		locked_by = NULL, locked_until = NULL WHERE status = ?`, o.table))
	res, err := db.ExecContext(ctx, q, StatusPending, o.now().UnixMilli(), StatusDead)
	if err != nil {
		return 0, fmt.Errorf("outbox: retry dead: %w", err)
	}
	return res.RowsAffected()
}

// NewID returns a random RFC 4122 version 4 UUID string.
func NewID() string {
	var b [16]byte
	if _, err := rand.Read(b[:]); err != nil {
		panic("outbox: crypto/rand failed: " + err.Error())
	}
	b[6] = (b[6] & 0x0f) | 0x40
	b[8] = (b[8] & 0x3f) | 0x80
	var s [36]byte
	hex.Encode(s[0:8], b[0:4])
	s[8] = '-'
	hex.Encode(s[9:13], b[4:6])
	s[13] = '-'
	hex.Encode(s[14:18], b[6:8])
	s[18] = '-'
	hex.Encode(s[19:23], b[8:10])
	s[23] = '-'
	hex.Encode(s[24:], b[10:])
	return string(s[:])
}
